mapper.select:
SELECT m.id, m.request_user, m.description, m.solve, DATE_FORMAT(m.request_date, '%Y-%m-%d') AS formatted_date, u.username AS owner, c.name AS customernamer FROM maintenance m LEFT JOIN maintenance_list ml ON m.id = ml.maintenance_id LEFT JOIN user u ON ml.user_id = u.id LEFT JOIN customer c ON ml.customer_id=c.id WHERE 1 = 1
AND m.id = #{id}
;
